function useControllableState<T>(opts: {
  value: T | undefined;
  defaultValue: T;
  onChange?: (next: T) => void;
}): [T, (next: T) => void] {
  const isControlled = opts.value !== undefined;
  const [internal, setInternal] = useState(opts.defaultValue);

  // pick the live value
  const value = isControlled ? (opts.value as T) : internal;

  const setValue = (next: T) => {
    setInternal(next);        // keep an internal copy in sync "to be safe"
    opts.onChange?.(next);
  };

  return [value, setValue];
}

// usage in a widget — note: value defaults to undefined when the prop is omitted
function Stepper({ value, defaultValue = 0, onChange }: StepperProps) {
  const [n, setN] = useControllableState({ value, defaultValue, onChange });
  return <button onClick={() => setN(n + 1)}>{n}</button>;
}
